fn solve(cafes: Vec<i8>) -> i8 {
    // Map each value to its last occurrence index
    let mut last_positions = std::collections::HashMap::new();
    
    for (idx, &value) in cafes.iter().enumerate() {
        last_positions.insert(value, idx);
    }
    
    // Find the value with the minimal last occurrence index
    let (result, _) = last_positions
        .into_iter()
        .min_by_key(|&(_, pos)| pos)
        .unwrap(); // Safe because input is non-empty and we inserted at least one entry
    
    result
}

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    cafes
        .iter()
        .enumerate()
        .rev() // Search from the end
        .find(|&(_, &val)| val == cafe)
        .map(|(idx, _)| idx)
        .unwrap_or(0) // Default to 0 if not found (though cafe should exist per problem context)
}